--==============================================================================
-- 4) PAQUETE PKG_CIFRADO
--==============================================================================
-- Requiere GRANT EXECUTE ON SYS.DBMS_CRYPTO al dueno de la boveda.
-- Claves de ejemplo para el taller; reemplazarlas en produccion por secretos
-- generados con RAWTOHEX(DBMS_CRYPTO.RANDOMBYTES(32)).
CREATE OR REPLACE PACKAGE pkg_cifrado AS
   FUNCTION cifrar (p_texto IN VARCHAR2) RETURN RAW;
   FUNCTION descifrar (p_dato IN RAW) RETURN VARCHAR2;
   FUNCTION huella (p_texto IN VARCHAR2) RETURN RAW;
END pkg_cifrado;
/

CREATE OR REPLACE PACKAGE BODY pkg_cifrado AS
   c_clave  CONSTANT RAW(32) := HEXTORAW('A1B2C3D4E5F60718293A4B5C6D7E8F90A1B2C3D4E5F60718293A4B5C6D7E8F90');
   c_clave2 CONSTANT RAW(32) := HEXTORAW('0F1E2D3C4B5A69788796A5B4C3D2E1F00F1E2D3C4B5A69788796A5B4C3D2E1F0');
   c_tipo   CONSTANT PLS_INTEGER := DBMS_CRYPTO.ENCRYPT_AES256
                                  + DBMS_CRYPTO.CHAIN_CBC
                                  + DBMS_CRYPTO.PAD_PKCS5;
   FUNCTION cifrar (p_texto IN VARCHAR2) RETURN RAW IS
      v_iv RAW(16);
   BEGIN
      IF p_texto IS NULL THEN RETURN NULL; END IF;
      v_iv := DBMS_CRYPTO.RANDOMBYTES(16);
      RETURN UTL_RAW.CONCAT(v_iv,
             DBMS_CRYPTO.ENCRYPT(UTL_I18N.STRING_TO_RAW(p_texto, 'AL32UTF8'),
                          c_tipo, c_clave, v_iv));
   END;
   FUNCTION descifrar (p_dato IN RAW) RETURN VARCHAR2 IS
   BEGIN
      IF p_dato IS NULL THEN RETURN NULL; END IF;
      RETURN UTL_I18N.RAW_TO_CHAR(
           DBMS_CRYPTO.DECRYPT(UTL_RAW.SUBSTR(p_dato, 17), c_tipo, c_clave,
                        UTL_RAW.SUBSTR(p_dato, 1, 16)), 'AL32UTF8');
   END;
   FUNCTION huella (p_texto IN VARCHAR2) RETURN RAW IS
   BEGIN
      IF p_texto IS NULL THEN RETURN NULL; END IF;
      RETURN DBMS_CRYPTO.MAC(
           UTL_I18N.STRING_TO_RAW(
             UPPER(TRANSLATE(p_texto, 'x.- ', 'x')), 'AL32UTF8'),
           DBMS_CRYPTO.HMAC_SH256, c_clave2);
   END;
END pkg_cifrado;
/

